import type { CatalogDifficulty, CatalogQuestion } from './testCatalog'

/**
 * Additional question bank, keyed by subtopic id. Merged into every subtopic by
 * `withMinimumQuestions` in testCatalog.ts (works for both base and demo themes).
 *
 * A spec is [text, correctAnswer, wrongAnswers, explanation, difficulty?, pos?].
 * `build` inserts the correct answer at `pos` and derives `correctIndex` from it,
 * so the answer key can never drift out of sync with the option order.
 */
type Spec = [
  text: string,
  correct: string,
  wrong: string[],
  explanation: string,
  difficulty?: CatalogDifficulty,
  pos?: number,
]

function build(prefix: string, start: number, specs: Spec[]): CatalogQuestion[] {
  return specs.map(([text, correct, wrong, explanation, difficulty = 'medium', pos = 0], i) => {
    const options = [...wrong]
    const index = Math.max(0, Math.min(pos, options.length))
    options.splice(index, 0, correct)
    return {
      id: `${prefix}-${start + i}`,
      text,
      options,
      correctIndex: index,
      explanation,
      difficulty,
    }
  })
}

